CREATE COLUMN TABLE "EXT"."WF_REPEXT_TIPO_REPARTO_FILE2"(
	"FECHA_BAJA" LONGDATE CS_LONGDATE,
	"FECHA_ALTA" LONGDATE CS_LONGDATE,
	"USUARIO" CHAR(10) CS_FIXEDSTRING,
	"FECHA_FIN" VARCHAR(8),
	"FECHA_INICIO" VARCHAR(8),
	"TIPO_REPARTO" CHAR(3) CS_FIXEDSTRING NOT NULL,
	"TIPO_AGENTE" CHAR(3) CS_FIXEDSTRING NOT NULL,
	"TIPO_PAGO" VARCHAR(3) NOT NULL,
	"CIA_CODIGO" CHAR(2) CS_FIXEDSTRING NOT NULL,
	"ID_TIPO_REPARTO" BIGINT CS_FIXED NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1)
)
UNLOAD PRIORITY 5 AUTO MERGE;
